use ai_platform_eval::{Result,parity_support::*};
use std::{path::PathBuf,collections::BTreeSet};
use serde_json::json;
#[tokio::main]async fn main(){match run().await{Ok(code)=>std::process::exit(code),Err(error)=>{println!("{}",json!({"status":"infrastructure_error","reason":error.to_string()}));std::process::exit(2)}}}
async fn run()->Result<i32>{let root=repo_root();let mut manifest_path=default_manifest();let mut gateway="http://127.0.0.1:8080/api/v1".to_string();let mut env_path=root.join(".env");let mut systems=SYSTEMS.iter().map(|s|s.to_string()).collect::<Vec<_>>();let mut tasks=BTreeSet::new();let mut thinking=None;let mut output=None;let mut validate=false;let mut args=std::env::args().skip(1);while let Some(arg)=args.next(){if arg=="--validate-only"{validate=true;continue}if ["--help","-h"].contains(&arg.as_str()){println!("native-agent-parity-benchmark [--manifest PATH] [--gateway-base-url URL] [--env-file PATH] [--systems ai_platform,hermes,openclaw] [--task ID] [--thinking-level off|low|medium|high] [--output-dir PATH] [--validate-only]");return Ok(0)}let value=args.next().ok_or("argument_requires_value")?;match arg.as_str(){"--manifest"=>manifest_path=value.into(),"--gateway-base-url"=>gateway=value,"--env-file"=>env_path=value.into(),"--systems"=>{systems=value.split(',').map(str::trim).filter(|s|!s.is_empty()).map(str::to_owned).collect();if systems.is_empty()||systems.iter().any(|s|!SYSTEMS.contains(&s.as_str())){return Err("invalid systems".into())}},"--task"=>{tasks.insert(value);},"--thinking-level"=>{if !["off","low","medium","high"].contains(&value.as_str()){return Err("invalid_thinking_level_override".into())}thinking=Some(value)},"--output-dir"=>output=Some(PathBuf::from(value)),_=>return Err(format!("unknown argument: {arg}").into())}}let m=load_manifest(&manifest_path)?;if validate{println!("{}",json!({"valid":true,"task_count":m["tasks"].as_array().unwrap().len(),"manifest_sha256":sha256_file(&manifest_path)?,"provider_calls":0}));return Ok(0)}let output_dir=output.unwrap_or_else(||root.join("reports/benchmark/results").join(chrono::Utc::now().format("native-parity-%Y%m%dT%H%M%SZ").to_string()));let summary=run_suite(SuiteOptions{manifest_path,output_dir,gateway_base_url:gateway,env_path,selected_systems:systems,selected_tasks:if tasks.is_empty(){None}else{Some(tasks)},thinking_level_override:thinking}).await?;println!("{}",summary["counts"]);Ok(if summary["acceptance_passed"]==true{0}else{1})}
